#!/usr/bin/env python3
"""Spawn a program in a pty, send keys with delays, capture raw output."""
import os, pty, sys, time, select, struct, fcntl, termios, signal, argparse, json

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--cols", type=int, default=100)
    ap.add_argument("--rows", type=int, default=30)
    ap.add_argument("--out", default="/tmp/h/out.bin")
    ap.add_argument("--script", default="")  # JSON list of [delay, keys]
    ap.add_argument("--env", default="")  # extra env KEY=VAL;KEY=VAL
    ap.add_argument("--wait", type=float, default=0.5)
    ap.add_argument("cmd", nargs=argparse.REMAINDER)
    a = ap.parse_args()
    cmd = a.cmd
    if cmd and cmd[0] == "--":
        cmd = cmd[1:]
    pid, fd = pty.fork()
    if pid == 0:
        env = dict(os.environ)
        env["TERM"] = env.get("TERM", "xterm-256color")
        for kv in a.env.split(";"):
            if "=" in kv:
                k, v = kv.split("=", 1)
                env[k] = v
        os.execvpe(cmd[0], cmd, env)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", a.rows, a.cols, 0, 0))
    out = bytearray()
    def drain(t):
        end = time.time() + t
        while True:
            rem = end - time.time()
            if rem <= 0:
                break
            r, _, _ = select.select([fd], [], [], rem)
            if fd in r:
                try:
                    d = os.read(fd, 65536)
                except OSError:
                    return False
                if not d:
                    return False
                out.extend(d)
        return True
    script = json.loads(a.script) if a.script else []
    alive = drain(a.wait)
    for step in script:
        delay, keys = step
        if not alive:
            break
        alive = drain(delay)
        if not alive:
            break
        if keys:
            os.write(fd, keys.encode("latin1") if isinstance(keys, str) else bytes(keys))
    if alive:
        drain(a.wait)
    try:
        os.kill(pid, signal.SIGKILL)
    except Exception:
        pass
    try:
        os.waitpid(pid, 0)
    except Exception:
        pass
    with open(a.out, "wb") as f:
        f.write(bytes(out))
    sys.stdout.write(f"captured {len(out)} bytes to {a.out}\n")

main()
