#!/bin/bash
# usage: tm.sh start <cols> <rows> <cmd...> | tm.sh keys <keys...> | tm.sh cap | tm.sh cape | tm.sh stop
case "$1" in
  start) shift; cols=$1; rows=$2; shift 2; tmux kill-session -t tt 2>/dev/null; tmux new-session -d -s tt -x $cols -y $rows "$@"; sleep 0.5;;
  keys) shift; tmux send-keys -t tt "$@"; sleep 0.3;;
  cap) tmux capture-pane -t tt -p;;
  cape) tmux capture-pane -t tt -p -e | cat -v;;
  stop) tmux kill-session -t tt 2>/dev/null;;
esac
