#!/usr/bin/env python3
"""Decode braille chart from tmux capture-pane text. Prints dot coordinates (dot_col, dot_row) relative to graph area."""
import sys
# braille dot bits: 0x1 (r0,c0) 0x2 (r1,c0) 0x4 (r2,c0) 0x8 (r0,c1) 0x10 (r1,c1) 0x20 (r2,c1) 0x40 (r3,c0) 0x80 (r3,c1)
BITS = {0x1:(0,0),0x2:(1,0),0x4:(2,0),0x8:(0,1),0x10:(1,1),0x20:(2,1),0x40:(3,0),0x80:(3,1)}
def decode(lines):
    pts = []
    for r, line in enumerate(lines):
        for c, ch in enumerate(line):
            o = ord(ch)
            if 0x2800 <= o <= 0x28FF:
                b = o - 0x2800
                for bit,(dr,dc) in BITS.items():
                    if b & bit:
                        pts.append((c*2+dc, r*4+dr))
    return pts
if __name__ == "__main__":
    lines = sys.stdin.read().split("\n")
    pts = decode(lines)
    pts.sort()
    for p in pts: print(p)
