import os, pty, sys, time, select, struct, fcntl, termios, signal, re
def run(cmd, cols, rows, wait=0.4, keys=None):
    pid, fd = pty.fork()
    if pid == 0:
        os.environ["TERM"]="xterm-256color"
        os.execvp(cmd[0], cmd)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
    out = bytearray(); end = time.time()+wait
    sent=False
    while time.time() < end:
        r,_,_ = select.select([fd],[],[],0.05)
        if fd in r:
            try: d = os.read(fd, 65536)
            except OSError: break
            if not d: break
            out += d
        if keys and not sent and time.time() > end - wait/2:
            os.write(fd, keys); sent=True
    try: os.kill(pid, signal.SIGKILL)
    except: pass
    os.waitpid(pid, 0)
    return bytes(out)
def positions(out):
    # return list of (row, col, text) for each MoveTo followed by text
    s = out.decode('utf-8', 'replace')
    res = []
    for m in re.finditer(r'\x1b\[(\d+);(\d+)H((?:\x1b\[[0-9;]*m|[^\x1b])*)', s):
        txt = re.sub(r'\x1b\[[0-9;]*m', '', m.group(3))
        res.append((int(m.group(1))-1, int(m.group(2))-1, txt))
    return res
if __name__ == "__main__":
    cols=int(sys.argv[1]); rows=int(sys.argv[2]); args=sys.argv[3:]
    out = run(["./executable"]+args, cols, rows)
    for p in positions(out): print(p)
