import os, pty, sys, time, select, struct, fcntl, termios, signal
def run(args, cols, rows, script, wait=0.6):
    pid, fd = pty.fork()
    if pid == 0:
        os.environ["TERM"]="xterm-256color"
        os.execvp("./executable", ["./executable"]+args)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
    out = bytearray()
    def drain(t):
        end = time.time()+t
        while True:
            rem = end-time.time()
            if rem <= 0: return
            r,_,_ = select.select([fd],[],[],rem)
            if fd in r:
                try: d = os.read(fd, 65536)
                except OSError: return
                out.extend(d)
    drain(0.3)
    t0 = time.time()
    for delay, keys in script:
        # busy wait for precision
        target = t0 + delay
        while time.time() < target:
            r,_,_ = select.select([fd],[],[],max(0, min(0.001, target-time.time())))
            if fd in r:
                try: out.extend(os.read(fd, 65536))
                except OSError: pass
        os.write(fd, keys.encode())
    drain(wait)
    try: os.kill(pid, signal.SIGKILL)
    except: pass
    os.waitpid(pid, 0)
    return bytes(out)
if __name__ == "__main__":
    import json
    args = json.loads(sys.argv[1]); script = json.loads(sys.argv[2])
    out = run(args, 120, 40, script)
    import re
    s = out.decode('utf-8','replace')
    m = re.search(r'(\S+ wpm\s+\S+ acc\s+\S+ sd)', s)
    print(m.group(1) if m else "no results")
    print(open(os.path.expanduser("~/.config/thokr/log.csv")).read().strip().split("\n")[-1])
