//! Terminal setup (raw mode, alternate screen) and the input event thread.

use crate::sys;
use std::io::Write;
use std::sync::atomic::{AtomicI32, Ordering};
use std::sync::mpsc::{channel, Receiver, Sender};
use std::time::{Duration, Instant};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum KeyCode {
    Char(char),
    Backspace,
    Enter,
    Tab,
    BackTab,
    Left,
    Right,
    Up,
    Down,
    Home,
    End,
    PageUp,
    PageDown,
    Delete,
    Insert,
    F(u8),
    Esc,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct KeyEvent {
    pub code: KeyCode,
    pub ctrl: bool,
    pub alt: bool,
    pub shift: bool,
}

impl KeyEvent {
    fn plain(code: KeyCode) -> Self {
        KeyEvent {
            code,
            ctrl: false,
            alt: false,
            shift: false,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Event {
    Key(KeyEvent),
    Resize,
    Tick,
}

/// Something the terminal sent us that is not a key press (mouse, cursor report, ...).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Parsed {
    Key(KeyEvent),
    Other,
}

// ---------------------------------------------------------------------------
// raw mode / screen handling
// ---------------------------------------------------------------------------

pub struct RawMode {
    fd: sys::Fd,
    original: sys::Termios,
}

impl RawMode {
    pub fn enable() -> std::io::Result<RawMode> {
        let fd: sys::Fd = 0;
        let mut ios = sys::Termios {
            c_iflag: 0,
            c_oflag: 0,
            c_cflag: 0,
            c_lflag: 0,
            c_line: 0,
            c_cc: [0; 32],
            c_ispeed: 0,
            c_ospeed: 0,
        };
        if unsafe { sys::tcgetattr(fd, &mut ios) } != 0 {
            return Err(std::io::Error::last_os_error());
        }
        let original = ios;
        unsafe { sys::cfmakeraw(&mut ios) };
        if unsafe { sys::tcsetattr(fd, sys::TCSANOW, &ios) } != 0 {
            return Err(std::io::Error::last_os_error());
        }
        Ok(RawMode { fd, original })
    }

    pub fn disable(&self) {
        unsafe {
            sys::tcsetattr(self.fd, sys::TCSANOW, &self.original);
        }
    }
}

pub fn write_out(bytes: &[u8]) {
    let mut out = std::io::stdout().lock();
    let _ = out.write_all(bytes);
    let _ = out.flush();
}

pub fn enter_alternate_screen() {
    write_out(b"\x1b[?1049h");
}

pub fn leave_alternate_screen_and_show_cursor() {
    write_out(b"\x1b[?1049l\x1b[?25h");
}

// ---------------------------------------------------------------------------
// SIGWINCH handling via a self pipe
// ---------------------------------------------------------------------------

static WINCH_PIPE_W: AtomicI32 = AtomicI32::new(-1);

extern "C" fn on_sigwinch(_sig: std::os::raw::c_int) {
    let fd = WINCH_PIPE_W.load(Ordering::Relaxed);
    if fd >= 0 {
        let b = [0u8; 1];
        unsafe {
            sys::write(fd, b.as_ptr() as *const _, 1);
        }
    }
}

fn install_sigwinch() -> Option<sys::Fd> {
    let mut fds = [0i32; 2];
    if unsafe { sys::pipe(fds.as_mut_ptr()) } != 0 {
        return None;
    }
    WINCH_PIPE_W.store(fds[1], Ordering::Relaxed);
    let act = sys::SigAction {
        sa_handler: on_sigwinch as usize,
        sa_mask: [0; 16],
        sa_flags: 0x1000_0000, // SA_RESTART
        sa_restorer: 0,
    };
    unsafe {
        sys::sigaction(sys::SIGWINCH, &act, std::ptr::null_mut());
    }
    Some(fds[0])
}

// ---------------------------------------------------------------------------
// event thread
// ---------------------------------------------------------------------------

pub fn spawn_event_thread(tick_rate: Duration) -> Receiver<Event> {
    let (tx, rx) = channel();
    std::thread::spawn(move || event_loop(tx, tick_rate));
    rx
}

fn event_loop(tx: Sender<Event>, tick_rate: Duration) {
    let winch_fd = install_sigwinch();
    let tty_fd: sys::Fd = 0;
    let mut parser = Parser::default();
    let mut buf = [0u8; 1024];
    let mut last_tick = Instant::now();
    loop {
        let timeout = tick_rate.saturating_sub(last_tick.elapsed());
        // poll(2) has millisecond granularity; round up like epoll does.
        let timeout_ms = ((timeout.as_micros() + 999) / 1000) as i32;
        let mut fds = [
            sys::PollFd {
                fd: tty_fd,
                events: sys::POLLIN,
                revents: 0,
            },
            sys::PollFd {
                fd: winch_fd.unwrap_or(-1),
                events: sys::POLLIN,
                revents: 0,
            },
        ];
        let n = unsafe { sys::poll(fds.as_mut_ptr(), 2, timeout_ms) };
        if n > 0 {
            if fds[0].revents != 0 {
                let r = unsafe { sys::read(tty_fd, buf.as_mut_ptr() as *mut _, buf.len()) };
                if r > 0 {
                    let r = r as usize;
                    parser.advance(&buf[..r], r == buf.len());
                    while let Some(p) = parser.next() {
                        if let Parsed::Key(k) = p {
                            if tx.send(Event::Key(k)).is_err() {
                                return;
                            }
                        }
                    }
                } else if r == 0 {
                    // EOF on the tty: nothing more will ever arrive.
                    std::thread::sleep(Duration::from_millis(50));
                }
            }
            if fds[1].revents != 0 {
                let mut tmp = [0u8; 64];
                unsafe {
                    sys::read(fds[1].fd, tmp.as_mut_ptr() as *mut _, tmp.len());
                }
                if tx.send(Event::Resize).is_err() {
                    return;
                }
            }
        }
        if last_tick.elapsed() >= tick_rate {
            if tx.send(Event::Tick).is_err() {
                return;
            }
            last_tick = Instant::now();
        }
    }
}

// ---------------------------------------------------------------------------
// ANSI input parser (modelled after the classic crossterm behaviour)
// ---------------------------------------------------------------------------

#[derive(Default)]
struct Parser {
    buffer: Vec<u8>,
    events: std::collections::VecDeque<Parsed>,
}

impl Parser {
    fn advance(&mut self, bytes: &[u8], more: bool) {
        for (idx, byte) in bytes.iter().enumerate() {
            let more = idx + 1 < bytes.len() || more;
            self.buffer.push(*byte);
            match parse_event(&self.buffer, more) {
                Ok(Some(ev)) => {
                    self.events.push_back(ev);
                    self.buffer.clear();
                }
                Ok(None) => {}
                Err(()) => {
                    self.buffer.clear();
                }
            }
        }
    }

    fn next(&mut self) -> Option<Parsed> {
        self.events.pop_front()
    }
}

type PResult = Result<Option<Parsed>, ()>;

fn key(code: KeyCode) -> PResult {
    Ok(Some(Parsed::Key(KeyEvent::plain(code))))
}

fn parse_event(buffer: &[u8], input_available: bool) -> PResult {
    if buffer.is_empty() {
        return Ok(None);
    }
    match buffer[0] {
        b'\x1b' => {
            if buffer.len() == 1 {
                if input_available {
                    Ok(None)
                } else {
                    key(KeyCode::Esc)
                }
            } else {
                match buffer[1] {
                    b'O' => {
                        if buffer.len() == 2 {
                            Ok(None)
                        } else {
                            match buffer[2] {
                                b'D' => key(KeyCode::Left),
                                b'C' => key(KeyCode::Right),
                                b'A' => key(KeyCode::Up),
                                b'B' => key(KeyCode::Down),
                                b'H' => key(KeyCode::Home),
                                b'F' => key(KeyCode::End),
                                val @ b'P'..=b'S' => key(KeyCode::F(1 + val - b'P')),
                                _ => Err(()),
                            }
                        }
                    }
                    b'[' => parse_csi(buffer),
                    b'\x1b' => key(KeyCode::Esc),
                    _ => parse_event(&buffer[1..], input_available).map(|ev| {
                        ev.map(|ev| match ev {
                            Parsed::Key(mut k) => {
                                k.alt = true;
                                Parsed::Key(k)
                            }
                            other => other,
                        })
                    }),
                }
            }
        }
        b'\r' => key(KeyCode::Enter),
        b'\t' => key(KeyCode::Tab),
        b'\x7f' => key(KeyCode::Backspace),
        c @ b'\x01'..=b'\x1a' => Ok(Some(Parsed::Key(KeyEvent {
            code: KeyCode::Char((c - 0x1 + b'a') as char),
            ctrl: true,
            alt: false,
            shift: false,
        }))),
        c @ b'\x1c'..=b'\x1f' => Ok(Some(Parsed::Key(KeyEvent {
            code: KeyCode::Char((c - 0x1c + b'4') as char),
            ctrl: true,
            alt: false,
            shift: false,
        }))),
        b'\0' => Ok(Some(Parsed::Key(KeyEvent {
            code: KeyCode::Char(' '),
            ctrl: true,
            alt: false,
            shift: false,
        }))),
        _ => parse_utf8_char(buffer).map(|c| {
            c.map(|c| {
                Parsed::Key(KeyEvent {
                    code: KeyCode::Char(c),
                    ctrl: false,
                    alt: false,
                    shift: c.is_uppercase(),
                })
            })
        }),
    }
}

fn parse_csi(buffer: &[u8]) -> PResult {
    if buffer.len() == 2 {
        return Ok(None);
    }
    match buffer[2] {
        b'[' => {
            if buffer.len() == 3 {
                Ok(None)
            } else {
                match buffer[3] {
                    val @ b'A'..=b'E' => key(KeyCode::F(1 + val - b'A')),
                    _ => Err(()),
                }
            }
        }
        b'D' => key(KeyCode::Left),
        b'C' => key(KeyCode::Right),
        b'A' => key(KeyCode::Up),
        b'B' => key(KeyCode::Down),
        b'H' => key(KeyCode::Home),
        b'F' => key(KeyCode::End),
        b'Z' => Ok(Some(Parsed::Key(KeyEvent {
            code: KeyCode::BackTab,
            ctrl: false,
            alt: false,
            shift: true,
        }))),
        b'M' => {
            // normal mouse encoding: ESC [ M cb cx cy
            if buffer.len() < 6 {
                Ok(None)
            } else {
                Ok(Some(Parsed::Other))
            }
        }
        b'<' => {
            // SGR mouse encoding: ESC [ < p1 ; p2 ; p3 (M|m)
            let last = *buffer.last().unwrap();
            if last != b'M' && last != b'm' {
                Ok(None)
            } else {
                let s = std::str::from_utf8(&buffer[3..buffer.len() - 1]).map_err(|_| ())?;
                let parts: Vec<&str> = s.split(';').collect();
                if parts.len() != 3 || parts.iter().any(|p| p.parse::<u16>().is_err()) {
                    return Err(());
                }
                Ok(Some(Parsed::Other))
            }
        }
        b';' => parse_csi_modifier_key_code(buffer),
        b'0'..=b'9' => {
            if buffer.len() == 3 {
                Ok(None)
            } else {
                let last = buffer[buffer.len() - 1];
                if !(64..=126).contains(&last) {
                    Ok(None)
                } else {
                    match last {
                        b'M' => parse_csi_rxvt_mouse(buffer),
                        b'~' => parse_csi_special_key_code(buffer),
                        b'R' => parse_csi_cursor_position(buffer),
                        _ => parse_csi_modifier_key_code(buffer),
                    }
                }
            }
        }
        _ => Err(()),
    }
}

fn csi_params(buffer: &[u8]) -> Result<Vec<&str>, ()> {
    // buffer is ESC [ ... final
    let s = std::str::from_utf8(&buffer[2..buffer.len() - 1]).map_err(|_| ())?;
    Ok(s.split(';').collect())
}

fn parse_csi_rxvt_mouse(buffer: &[u8]) -> PResult {
    let parts = csi_params(buffer)?;
    if parts.len() < 3 {
        return Err(());
    }
    for p in &parts[..3] {
        p.parse::<u16>().map_err(|_| ())?;
    }
    Ok(Some(Parsed::Other))
}

fn parse_csi_cursor_position(buffer: &[u8]) -> PResult {
    let parts = csi_params(buffer)?;
    if parts.len() < 2 {
        return Err(());
    }
    parts[0].parse::<u16>().map_err(|_| ())?;
    parts[1].parse::<u16>().map_err(|_| ())?;
    Ok(Some(Parsed::Other))
}

fn modifiers_from_param(p: u8) -> (bool, bool, bool) {
    // returns (shift, alt, ctrl)
    match p {
        2 => (true, false, false),
        3 => (false, true, false),
        4 => (true, true, false),
        5 => (false, false, true),
        6 => (true, false, true),
        7 => (false, true, true),
        8 => (true, true, true),
        _ => (false, false, false),
