    let parts = csi_params(buffer)?;
    let modifier_mask = if parts.len() > 1 {
        parts[1].parse::<u8>().map_err(|_| ())?
    } else {
        0
    };
    let (shift, alt, ctrl) = modifiers_from_param(modifier_mask);
