                        b'~' => parse_csi_special_key_code(buffer),
                        b'R' => parse_csi_cursor_position(buffer),
                        _ => parse_csi_modifier_key_code(buffer),
                    }
                }
            }
        }
        _ => Err(()),
    }
}

