//! A cell buffer with double-buffered diffing and an ANSI backend, modelled on the behaviour
//! of the classic `tui` crossterm backend.

use crate::unicode::str_width;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct Rect {
    pub x: u16,
    pub y: u16,
    pub width: u16,
    pub height: u16,
}

impl Rect {
    /// Creates a rect, clipping the area so that it never exceeds `u16::MAX` cells while
    /// preserving the aspect ratio.
    pub fn new(x: u16, y: u16, width: u16, height: u16) -> Rect {
        let max_area = u16::MAX;
        let (w, h) = if u32::from(width) * u32::from(height) > u32::from(max_area) {
            let aspect_ratio = f64::from(width) / f64::from(height);
            let max_area_f = f64::from(max_area);
            let height_f = (max_area_f / aspect_ratio).sqrt();
            let width_f = height_f * aspect_ratio;
            (width_f as u16, height_f as u16)
        } else {
            (width, height)
        };
        Rect {
            x,
            y,
            width: w,
            height: h,
        }
    }
    pub fn area(&self) -> u16 {
        self.width * self.height
    }
    pub fn left(&self) -> u16 {
        self.x
    }
    pub fn right(&self) -> u16 {
        self.x.saturating_add(self.width)
    }
    pub fn top(&self) -> u16 {
        self.y
    }
    pub fn bottom(&self) -> u16 {
        self.y.saturating_add(self.height)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Color {
    Reset,
    Green,
    Red,
}

pub mod modifier {
    pub const BOLD: u16 = 0b0000_0000_0001;
    pub const DIM: u16 = 0b0000_0000_0010;
    pub const ITALIC: u16 = 0b0000_0000_0100;
    pub const UNDERLINED: u16 = 0b0000_0000_1000;
    pub const SLOW_BLINK: u16 = 0b0000_0001_0000;
    pub const RAPID_BLINK: u16 = 0b0000_0010_0000;
    pub const REVERSED: u16 = 0b0000_0100_0000;
    pub const CROSSED_OUT: u16 = 0b0001_0000_0000;
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Style {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub add_modifier: u16,
    pub sub_modifier: u16,
}

impl Default for Style {
    fn default() -> Self {
        Style {
            fg: None,
            bg: None,
            add_modifier: 0,
            sub_modifier: 0,
        }
    }
}

impl Style {
    pub fn fg(mut self, c: Color) -> Self {
        self.fg = Some(c);
        self
    }
    pub fn add_modifier(mut self, m: u16) -> Self {
        self.sub_modifier &= !m;
        self.add_modifier |= m;
        self
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Cell {
    pub symbol: String,
    pub fg: Color,
    pub bg: Color,
    pub modifier: u16,
}

impl Default for Cell {
    fn default() -> Self {
        Cell {
            symbol: " ".to_string(),
            fg: Color::Reset,
            bg: Color::Reset,
            modifier: 0,
        }
    }
}

impl Cell {
    pub fn set_symbol(&mut self, s: &str) -> &mut Cell {
        self.symbol.clear();
        self.symbol.push_str(s);
        self
    }
    pub fn set_char(&mut self, c: char) -> &mut Cell {
        self.symbol.clear();
        self.symbol.push(c);
        self
    }
