    while let Some((i, c)) = iter.next() {
        let mut end = i + c.len_utf8();
        let mut prev_zwj = c == '\\u{200D}';
        while let Some(&(j, n)) = iter.peek() {
            let attach = is_combining(n)
                || n == '\\u{200D}'
                || (0x1F3FB..=0x1F3FF).contains(&(n as u32))
                || prev_zwj
                || (c == '\\r' && n == '\\n' && end == i + 1);
            if attach {
                prev_zwj = n == '\\u{200D}';
                end = j + n.len_utf8();
                iter.next();
            } else {
                break;
            }
        }
        out.push(&s[i..end]);
    }
    out
}
