//! Widgets: word wrapped paragraph and a braille line chart, replicating the classic `tui`
//! rendering behaviour.

use crate::buffer::{modifier, Buffer, Color, Rect, Style};
use crate::unicode::str_width;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Alignment {
    Left,
    Center,
    Right,
}

#[derive(Debug, Clone)]
pub struct StyledGrapheme<'a> {
    pub symbol: &'a str,
    pub style: Style,
}

const NBSP: &str = "\u{00a0}";

/// Word wraps a single line of styled graphemes (trim = true) into lines, returning for each
/// line its graphemes and width.
pub fn word_wrap<'a>(symbols: &[StyledGrapheme<'a>], max_line_width: u16) -> Vec<(Vec<StyledGrapheme<'a>>, u16)> {
    let mut lines = Vec::new();
    if max_line_width == 0 {
        return lines;
    }
    // the paragraph appends a "\n" terminator after the text
    let mut iter = symbols.iter().cloned().chain(std::iter::once(StyledGrapheme {
        symbol: "\n",
        style: Style::default(),
    }));
    let mut next_line: Vec<StyledGrapheme<'a>> = Vec::new();
    loop {
        let mut current_line = std::mem::take(&mut next_line);
        let mut current_line_width: u16 = current_line.iter().map(|g| str_width(g.symbol) as u16).sum();
        let mut symbols_to_last_word_end: usize = 0;
        let mut width_to_last_word_end: u16 = 0;
        let mut prev_whitespace = false;
        let mut symbols_exhausted = true;
        while let Some(StyledGrapheme { symbol, style }) = iter.next() {
            symbols_exhausted = false;
            let symbol_whitespace = symbol.chars().all(char::is_whitespace) && symbol != NBSP;
            if str_width(symbol) as u16 > max_line_width
                || (symbol_whitespace && symbol != "\n" && current_line_width == 0)
            {
                continue;
            }
            if symbol == "\n" {
                if prev_whitespace {
                    current_line_width = width_to_last_word_end;
                    current_line.truncate(symbols_to_last_word_end);
                }
                break;
            }
            if symbol_whitespace && !prev_whitespace {
                symbols_to_last_word_end = current_line.len();
                width_to_last_word_end = current_line_width;
            }
            current_line.push(StyledGrapheme { symbol, style });
            current_line_width += str_width(symbol) as u16;
            if current_line_width > max_line_width {
                let (truncate_at, truncated_width) = if symbols_to_last_word_end != 0 {
                    (symbols_to_last_word_end, width_to_last_word_end)
                } else {
                    (current_line.len() - 1, max_line_width)
                };
                {
                    let remainder = &current_line[truncate_at..];
                    if let Some(nonwhite) = remainder
                        .iter()
                        .position(|g| !g.symbol.chars().all(char::is_whitespace))
                    {
                        next_line.extend_from_slice(&remainder[nonwhite..]);
                    }
                }
                current_line.truncate(truncate_at);
                current_line_width = truncated_width;
                break;
            }
            prev_whitespace = symbol_whitespace;
        }
        if symbols_exhausted && current_line.is_empty() {
            break;
        }
        lines.push((current_line, current_line_width));
    }
    lines
}

fn line_offset(line_width: u16, text_area_width: u16, alignment: Alignment) -> u16 {
    match alignment {
        Alignment::Center => (text_area_width / 2).saturating_sub(line_width / 2),
        Alignment::Right => text_area_width.saturating_sub(line_width),
        Alignment::Left => 0,
    }
}

/// Renders a word-wrapped paragraph made of a single line of styled graphemes.
pub fn render_paragraph(buf: &mut Buffer, area: Rect, symbols: &[StyledGrapheme], alignment: Alignment) {
    if area.height < 1 || area.width < 1 {
        return;
    }
    let lines = word_wrap(symbols, area.width);
    let mut y: u16 = 0;
    for (line, line_width) in lines {
        let mut x = line_offset(line_width, area.width, alignment);
        for g in line {
            let cx = area.left() + x;
            let cy = area.top() + y;
            if buf.in_bounds(cx, cy) {
                let cell = buf.get_mut(cx, cy);
                cell.set_symbol(if g.symbol.is_empty() { " " } else { g.symbol });
                cell.set_style(g.style);
            }
            x += str_width(g.symbol) as u16;
        }
        y += 1;
        if y >= area.height {
            break;
        }
    }
}

/// Writes a plain string with a style at a position (clipped to the buffer).
pub fn render_string(buf: &mut Buffer, x: u16, y: u16, s: &str, width: usize, style: Style) {
    if !buf.in_bounds(x, y) {
        return;
    }
    buf.set_stringn(x, y, s, width, style);
}

// ---------------------------------------------------------------------------
// chart
// ---------------------------------------------------------------------------

#[derive(Default, Debug)]
struct ChartLayout {
    label_x: Option<u16>,
    label_y: Option<u16>,
    axis_x: Option<u16>,
    axis_y: Option<u16>,
    title_x: Option<(u16, u16)>,
    title_y: Option<(u16, u16)>,
    graph_area: Rect,
}

pub struct Chart<'a> {
    pub x_labels: Vec<&'a str>,
    pub y_labels: Vec<&'a str>,
    pub x_bounds: [f64; 2],
    pub y_bounds: [f64; 2],
    pub x_title: &'a str,
    pub y_title: &'a str,
    pub data: &'a [(f64, f64)],
}

impl<'a> Chart<'a> {
    fn max_width_of_labels_left_of_y_axis(&self, area: Rect, has_y_axis: bool) -> u16 {
        let mut max_width = self.y_labels.iter().map(|l| str_width(l)).max().unwrap_or(0) as u16;
        if let Some(first) = self.x_labels.first() {
            let first_label_width = str_width(first) as u16;
            // x labels alignment: Left
            let y_axis_offset = if has_y_axis { 1 } else { 0 };
            let width_left_of_y_axis = first_label_width.saturating_sub(y_axis_offset);
            max_width = std::cmp::max(max_width, width_left_of_y_axis);
        }
        max_width.min(area.width / 3)
    }

    fn layout(&self, area: Rect) -> ChartLayout {
        let mut layout = ChartLayout::default();
        if area.height == 0 || area.width == 0 {
            return layout;
        }
        let mut x = area.left();
        let mut y = area.bottom() - 1;

        if y > area.top() {
            layout.label_x = Some(y);
            y -= 1;
        }

        layout.label_y = Some(x);
        x += self.max_width_of_labels_left_of_y_axis(area, true);

        if y > area.top() {
            layout.axis_x = Some(y);
            y -= 1;
        }

        if x + 1 < area.right() {
            layout.axis_y = Some(x);
            x += 1;
        }

        if x < area.right() && y > 1 {
            layout.graph_area = Rect {
                x,
                y: area.top(),
                width: area.right() - x,
                height: y - area.top() + 1,
            };
        }

        let w = str_width(self.x_title) as u16;
        if w < layout.graph_area.width && layout.graph_area.height > 2 {
            layout.title_x = Some((x + layout.graph_area.width - w, y));
        }
        let w = str_width(self.y_title) as u16;
        if w + 1 < layout.graph_area.width && layout.graph_area.height > 2 {
            layout.title_y = Some((x, area.top()));
        }
        layout
    }

    fn render_label(buf: &mut Buffer, label: &str, label_area: Rect, alignment: Alignment, style: Style) {
        let label_width = str_width(label) as u16;
        let bounded = label_area.width.min(label_width);
        let x = match alignment {
            Alignment::Left => label_area.left(),
            Alignment::Center => label_area.left() + label_area.width / 2 - bounded / 2,
            Alignment::Right => label_area.right() - bounded,
        };
        render_string(buf, x, label_area.top(), label, bounded as usize, style);
    }

    fn render_x_labels(&self, buf: &mut Buffer, layout: &ChartLayout, chart_area: Rect, graph_area: Rect) {
        let y = match layout.label_x {
            Some(y) => y,
            None => return,
        };
        let labels_len = self.x_labels.len() as u16;
        if labels_len < 2 {
            return;
        }
        let bold = Style::default().add_modifier(modifier::BOLD);
        let width_between_ticks = graph_area.width / labels_len;
        // first label (labels alignment Left => rendered Right against the y axis)
        let (min_x, max_x) = (chart_area.left(), graph_area.left());
        let label_area = Rect {
            x: min_x,
            y,
            width: max_x - min_x,
            height: 1,
        };
        Self::render_label(buf, self.x_labels[0], label_area, Alignment::Right, bold);

        for (i, label) in self.x_labels[1..self.x_labels.len() - 1].iter().enumerate() {
            let x = graph_area.left() + (i + 1) as u16 * width_between_ticks + 1;
            let label_area = Rect {
                x,
                y,
                width: width_between_ticks.saturating_sub(1),
                height: 1,
            };
            Self::render_label(buf, label, label_area, Alignment::Center, bold);
        }

        let x = graph_area.right() - width_between_ticks;
        let label_area = Rect {
            x,
            y,
            width: width_between_ticks,
            height: 1,
        };
        Self::render_label(buf, self.x_labels[self.x_labels.len() - 1], label_area, Alignment::Right, bold);
    }

    fn render_y_labels(&self, buf: &mut Buffer, layout: &ChartLayout, chart_area: Rect, graph_area: Rect) {
        let x = match layout.label_y {
            Some(x) => x,
            None => return,
        };
        let labels_len = self.y_labels.len() as u16;
        if labels_len < 2 {
            return;
        }
        let bold = Style::default().add_modifier(modifier::BOLD);
        for (i, label) in self.y_labels.iter().enumerate() {
            let dy = i as u16 * (graph_area.height - 1) / (labels_len - 1);
            if dy < graph_area.bottom() {
                let label_area = Rect {
                    x,
                    y: graph_area.bottom() - 1 - dy,
                    width: (graph_area.left() - chart_area.left()).saturating_sub(1),
                    height: 1,
                };
                Self::render_label(buf, label, label_area, Alignment::Left, bold);
            }
        }
    }

    pub fn render(&self, buf: &mut Buffer, area: Rect) {
        if area.area() == 0 {
            return;
        }
        let layout = self.layout(area);
        let graph_area = layout.graph_area;
        if graph_area.width < 1 || graph_area.height < 1 {
            return;
        }

        self.render_x_labels(buf, &layout, area, graph_area);
        self.render_y_labels(buf, &layout, area, graph_area);

        if let Some(y) = layout.axis_x {
            for x in graph_area.left()..graph_area.right() {
                buf.get_mut(x, y).set_symbol("─");
            }
        }
        if let Some(x) = layout.axis_y {
            for y in graph_area.top()..graph_area.bottom() {
                buf.get_mut(x, y).set_symbol("│");
            }
        }
        if let (Some(y), Some(x)) = (layout.axis_x, layout.axis_y) {
            buf.get_mut(x, y).set_symbol("└");
        }

        // dataset
        let mut canvas = BrailleCanvas::new(graph_area, self.x_bounds, self.y_bounds);
        for p in self.data {
            canvas.point(p.0, p.1);
        }
        for w in self.data.windows(2) {
            canvas.line(w[0].0, w[0].1, w[1].0, w[1].1);
        }
        canvas.render(buf);

        if let Some((x, y)) = layout.title_x {
            let width = graph_area.right().saturating_sub(x);
            render_string(buf, x, y, self.x_title, width as usize, Style::default());
        }
        if let Some((x, y)) = layout.title_y {
            let width = graph_area.right().saturating_sub(x);
            render_string(buf, x, y, self.y_title, width as usize, Style::default());
        }
    }
}

const BRAILLE_DOTS: [[u16; 2]; 4] = [
    [0x0001, 0x0008],
    [0x0002, 0x0010],
    [0x0004, 0x0020],
    [0x0040, 0x0080],
];

struct BrailleCanvas {
    area: Rect,
    cells: Vec<u16>,
    width: usize,
    x_bounds: [f64; 2],
    y_bounds: [f64; 2],
    resolution: (f64, f64),
}

impl BrailleCanvas {
    fn new(area: Rect, x_bounds: [f64; 2], y_bounds: [f64; 2]) -> Self {
        BrailleCanvas {
            area,
            cells: vec![0x2800; area.width as usize * area.height as usize],
            width: area.width as usize,
            x_bounds,
            y_bounds,
            resolution: (f64::from(area.width) * 2.0, f64::from(area.height) * 4.0),
        }
    }

    fn get_point(&self, x: f64, y: f64) -> Option<(usize, usize)> {
        let left = self.x_bounds[0];
        let right = self.x_bounds[1];
        let top = self.y_bounds[1];
        let bottom = self.y_bounds[0];
        if x < left || x > right || y < bottom || y > top {
            return None;
        }
        let width = (right - left).abs();
        let height = (top - bottom).abs();
        if width == 0.0 || height == 0.0 {
            return None;
        }
        let xi = ((x - left) * (self.resolution.0 - 1.0) / width) as usize;
        let yi = ((top - y) * (self.resolution.1 - 1.0) / height) as usize;
        Some((xi, yi))
    }

    fn paint(&mut self, x: usize, y: usize) {
        let index = y / 4 * self.width + x / 2;
        if let Some(c) = self.cells.get_mut(index) {
            *c |= BRAILLE_DOTS[y % 4][x % 2];
        }
    }

    fn point(&mut self, x: f64, y: f64) {
        if let Some((xi, yi)) = self.get_point(x, y) {
            self.paint(xi, yi);
        }
    }

    fn line(&mut self, x1: f64, y1: f64, x2: f64, y2: f64) {
        let (x1, y1) = match self.get_point(x1, y1) {
            Some(p) => p,
            None => return,
        };
        let (x2, y2) = match self.get_point(x2, y2) {
            Some(p) => p,
            None => return,
        };
        let (dx, x_range) = if x2 >= x1 { (x2 - x1, x1..=x2) } else { (x1 - x2, x2..=x1) };
        let (dy, y_range) = if y2 >= y1 { (y2 - y1, y1..=y2) } else { (y1 - y2, y2..=y1) };
        if dx == 0 {
            for y in y_range {
                self.paint(x1, y);
            }
        } else if dy == 0 {
            for x in x_range {
                self.paint(x, y1);
            }
        } else if dy < dx {
            if x2 >= x1 {
                self.draw_line_low(x1, y1, x2, y2);
            } else {
                self.draw_line_low(x2, y2, x1, y1);
            }
        } else if y2 >= y1 {
            self.draw_line_high(x1, y1, x2, y2);
        } else {
            self.draw_line_high(x2, y2, x1, y1);
        }
    }

    fn draw_line_low(&mut self, x1: usize, y1: usize, x2: usize, y2: usize) {
        let dx = (x2 - x1) as isize;
        let dy = (y2 as isize - y1 as isize).abs();
        let mut d = 2 * dy - dx;
        let mut y = y1;
        for x in x1..=x2 {
            self.paint(x, y);
            if d > 0 {
                y = if y1 > y2 { y.saturating_sub(1) } else { y.saturating_add(1) };
                d -= 2 * dx;
            }
            d += 2 * dy;
        }
    }

    fn draw_line_high(&mut self, x1: usize, y1: usize, x2: usize, y2: usize) {
        let dx = (x2 as isize - x1 as isize).abs();
        let dy = (y2 - y1) as isize;
        let mut d = 2 * dx - dy;
        let mut x = x1;
        for y in y1..=y2 {
            self.paint(x, y);
            if d > 0 {
                x = if x1 > x2 { x.saturating_sub(1) } else { x.saturating_add(1) };
                d -= 2 * dy;
            }
            d += 2 * dx;
        }
    }

    fn render(&self, buf: &mut Buffer) {
        for (i, &c) in self.cells.iter().enumerate() {
            if c != 0x2800 {
                let x = (i % self.width) as u16 + self.area.left();
                let y = (i / self.width) as u16 + self.area.top();
                if let Some(ch) = char::from_u32(c as u32) {
                    buf.get_mut(x, y).set_char(ch).set_fg(Color::Reset);
                }
            }
        }
    }
}
