            accuracy: 0.0,
            std_dev: 0.0,
            wpm_coords: Vec::new(),
        }
    }

    pub fn on_tick(&mut self) {
        if let Some(s) = self.seconds_remaining.as_mut() {
            *s -= 0.1;
        }
    }

