        self.started_at.is_some()
    }

    pub fn has_finished(&self) -> bool {
        self.input.len() == self.prompt_chars.len()
            || matches!(self.seconds_remaining, Some(s) if s <= 0.0)
    }

    pub fn write(&mut self, c: char) {
        let now = Instant::now();
        if self.started_at.is_none() {
            self.started_at = Some(now);
        }
        let idx = self.input.len();
        let outcome = if self.prompt_chars.get(idx) == Some(&c) {
            Outcome::Correct
        } else {
            Outcome::Incorrect
        };
        self.input.push(Input {
            ch: c,
            outcome,
            timestamp: now,
        });
    }

    pub fn backspace(&mut self) {
        self.input.pop();
    }

