        let started = match self.started_at {
            Some(s) => s,
            None => return,
        };
        let now = Instant::now();
        let elapsed = now.duration_since(started).as_millis() as f64 / 1000.0;
        self.elapsed_secs = Some(elapsed);
        let limit = elapsed.ceil();

        // correct characters bucketed into whole seconds
        let mut buckets: BTreeMap<u64, u64> = BTreeMap::new();
        for i in self.input.iter().filter(|i| i.outcome == Outcome::Correct) {
            let t = i.timestamp.duration_since(started).as_secs_f64();
            let mut s = t.ceil();
            if s < 1.0 {
                s = 1.0;
            }
            *buckets.entry(s as u64).or_insert(0) += 1;
        }
        let per_sec: Vec<(f64, f64)> = buckets.into_iter().map(|(k, v)| (k as f64, v as f64)).collect();

        let mut coords = Vec::with_capacity(per_sec.len());
        let mut cumulative = 0.0;
        for &(secs, count) in &per_sec {
            cumulative += count;
            let denom = if secs < limit { secs } else { limit };
            coords.push((secs, (cumulative / 5.0) / (denom / 60.0)));
        }
        self.wpm_coords = coords;

        let counts: Vec<f64> = per_sec.iter().take(per_sec.len().saturating_sub(1)).map(|p| p.1).collect();
        self.std_dev = population_std_dev(&counts);

        self.wpm = self.wpm_coords.last().map(|p| p.1.ceil()).unwrap_or(0.0);
        let total = self.input.len();
        let correct = self.input.iter().filter(|i| i.outcome == Outcome::Correct).count();
        self.accuracy = if total > 0 {
            (correct as f64 / total as f64 * 100.0).round()
        } else {
            0.0
        };
    }

    /// Upper x bound of the results chart.
    pub fn max_x(&self) -> f64 {
        let v = match self.wpm_coords.last() {
            Some(p) => p.0,
            None => self.seconds_remaining.unwrap_or(1.0),
        };
        if v > 1.0 {
            v
        } else {
            1.0
        }
    }

    /// Upper y bound of the results chart.
    pub fn max_y(&self) -> f64 {
        let mut m = 0.0f64;
        for p in &self.wpm_coords {
            if p.1 > m || p.1.is_nan() {
                m = p.1;
            }
        }
        m.round()
    }
}

fn population_std_dev(values: &[f64]) -> f64 {
    if values.is_empty() {
        return 0.0;
    }
    let n = values.len() as f64;
    let mean = values.iter().sum::<f64>() / n;
    let var = values.iter().map(|v| (v - mean) * (v - mean)).sum::<f64>() / n;
    var.sqrt()
}
