import re, sys, subprocess, os, pty, select, time, json
def run_tty(args):
    pid, fd = pty.fork()
    if pid == 0:
        os.execvp("./executable", ["./executable"]+args)
    out = bytearray(); 
    while True:
        r,_,_ = select.select([fd],[],[],1.0)
        if not r: break
        try: d = os.read(fd, 65536)
        except OSError: break
        if not d: break
        out += d
    os.waitpid(pid, 0)
    return bytes(out).decode().replace('\r\n','\n')
def pieces(d):
    out = []
    pos = 0
    while pos < len(d):
        if not d.startswith('\x1b[0m', pos):
            print("UNMATCHED at", pos, repr(d[pos:pos+40])); break
        pos += 4
        style = ''
        m = re.match(r'(\x1b\[[1-9][0-9;]*m)+', d[pos:])
        if m: style = m.group(0); pos += m.end()
        end = d.index('\x1b[0m', pos)
        out.append((style, d[pos:end])); pos = end + 4
    return out
for args in json.loads(sys.argv[1]):
    print("=== ", args)
