#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ArgId {
    FullSentences,
    SupportedLanguage,
    Prompt,
    NumberOfSecs,
    NumberOfWords,
}

impl ArgId {
    fn long(self) -> &'static str {
        match self {
            ArgId::FullSentences => "full-sentences",
            ArgId::SupportedLanguage => "supported-language",
            ArgId::Prompt => "prompt",
            ArgId::NumberOfSecs => "number-of-secs",
            ArgId::NumberOfWords => "number-of-words",
        }
    }
    fn short(self) -> char {
        match self {
            ArgId::FullSentences => 'f',
            ArgId::SupportedLanguage => 'l',
            ArgId::Prompt => 'p',
            ArgId::NumberOfSecs => 's',
            ArgId::NumberOfWords => 'w',
        }
    }
    fn value_name(self) -> &'static str {
        match self {
            ArgId::FullSentences => "NUMBER_OF_SENTENCES",
            ArgId::SupportedLanguage => "SUPPORTED_LANGUAGE",
            ArgId::Prompt => "PROMPT",
            ArgId::NumberOfSecs => "NUMBER_OF_SECS",
            ArgId::NumberOfWords => "NUMBER_OF_WORDS",
        }
    }
    /// `--long <VALUE_NAME>`
    fn display(self) -> String {
        format!("--{} <{}>", self.long(), self.value_name())
    }
    fn from_long(s: &str) -> Option<ArgId> {
        ALL.iter().copied().find(|a| a.long() == s)
    }
    fn from_short(c: char) -> Option<ArgId> {
        ALL.iter().copied().find(|a| a.short() == c)
    }
}

/// Declaration order (also the order used for "did you mean" tie breaking).
const ALL: [ArgId; 5] = [
    ArgId::FullSentences,
    ArgId::SupportedLanguage,
    ArgId::Prompt,
    ArgId::NumberOfWords,
    ArgId::NumberOfSecs,
];

const LONG_FLAGS: [&str; 7] = [
    "full-sentences",
    "supported-language",
    "prompt",
    "number-of-words",
    "number-of-secs",
    "help",
    "version",
];

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PStyle {
    Default,
    Error,
    Warning,
    Good,
}

type Piece = (PStyle, String);

fn piece(style: PStyle, s: &str) -> Piece {
    (style, s.to_string())
}

fn render_pieces(pieces: &[Piece], color: bool) -> Vec<u8> {
    let mut out = Vec::new();
    for (style, text) in pieces {
        if color {
            out.extend_from_slice(b"\x1b[0m");
            match style {
                PStyle::Default => {}
                PStyle::Error => out.extend_from_slice(b"\x1b[1m\x1b[31m"),
                PStyle::Warning => out.extend_from_slice(b"\x1b[33m"),
                PStyle::Good => out.extend_from_slice(b"\x1b[32m"),
            }
            out.extend_from_slice(text.as_bytes());
            out.extend_from_slice(b"\x1b[0m");
        } else {
            out.extend_from_slice(text.as_bytes());
        }
    }
    out
}

fn env_allows_color() -> bool {
    match std::env::var_os("TERM") {
        None => return false,
        Some(k) => {
            if k == "dumb" {
                return false;
            }
        }
    }
    std::env::var_os("NO_COLOR").is_none()
}

fn emit(pieces: &[Piece], stderr: bool) {
    let is_tty = if stderr {
        std::io::stderr().is_terminal()
    } else {
        std::io::stdout().is_terminal()
    };
    let color = is_tty && env_allows_color();
    let bytes = render_pieces(pieces, color);
    if stderr {
        let mut e = std::io::stderr().lock();
        let _ = e.write_all(&bytes);
        let _ = e.flush();
    } else {
        let mut o = std::io::stdout().lock();
        let _ = o.write_all(&bytes);
        let _ = o.flush();
    }
}

fn bin_name() -> String {
    std::env::args_os()
        .next()
        .and_then(|a| {
            std::path::Path::new(&a)
                .file_name()
                .map(|f| f.to_string_lossy().into_owned())
        })
        .unwrap_or_else(|| "thokr".to_string())
}

fn usage_line(used: &[ArgId]) -> String {
    if used.is_empty() {
        format!("{} [OPTIONS]", bin_name())
    } else {
        let mut s = bin_name();
        for a in used {
            s.push(' ');
            s.push_str(&a.display());
        }
        s
    }
}

fn error_head() -> Vec<Piece> {
    vec![piece(PStyle::Error, "error:"), piece(PStyle::Default, " ")]
}

fn error_tail(pieces: &mut Vec<Piece>) {
    pieces.push(piece(PStyle::Default, "\n\nFor more information try "));
    pieces.push(piece(PStyle::Good, "--help"));
    pieces.push(piece(PStyle::Default, "\n"));
}

fn usage_block(pieces: &mut Vec<Piece>, used: &[ArgId]) {
    pieces.push(piece(PStyle::Default, "\n\n"));
    pieces.push(piece(
        PStyle::Default,
        &format!("USAGE:\n    {}", usage_line(used)),
    ));
}

fn possible_values_block(pieces: &mut Vec<Piece>) {
    pieces.push(piece(PStyle::Default, "\n\t[possible values: "));
    for (i, v) in LANGUAGES.iter().enumerate() {
        if i > 0 {
            pieces.push(piece(PStyle::Default, ", "));
        }
        pieces.push(piece(PStyle::Good, v));
    }
    pieces.push(piece(PStyle::Default, "]"));
}

fn fail(pieces: Vec<Piece>) -> ! {
    emit(&pieces, true);
    std::process::exit(2);
}

fn err_unknown_argument(arg: &str, did_you_mean: Option<&str>, used: &[ArgId]) -> ! {
    let mut p = error_head();
    p.push(piece(PStyle::Default, "Found argument '"));
    p.push(piece(PStyle::Warning, arg));
    p.push(piece(
        PStyle::Default,
        "' which wasn't expected, or isn't valid in this context",
    ));
    if let Some(s) = did_you_mean {
        p.push(piece(PStyle::Default, "\n\n\tDid you mean '"));
        p.push(piece(PStyle::Good, &format!("--{}", s)));
        p.push(piece(PStyle::Default, "'?"));
    }
    if arg.starts_with('-') {
        p.push(piece(
            PStyle::Default,
            &format!(
                "\n\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`",
                arg, arg
            ),
        ));
    }
    usage_block(&mut p, used);
    error_tail(&mut p);
    fail(p)
}

fn err_empty_value(arg: ArgId) -> ! {
    let mut p = error_head();
    p.push(piece(PStyle::Default, "The argument '"));
    p.push(piece(PStyle::Warning, &arg.display()));
    p.push(piece(
        PStyle::Default,
        "' requires a value but none was supplied",
    ));
    if arg == ArgId::SupportedLanguage {
        possible_values_block(&mut p);
    }
    usage_block(&mut p, &[]);
    error_tail(&mut p);
    fail(p)
