    p.push(piece(d, ""));
    p.push(piece(d, "\n"));
    emit(&p, false);
    std::process::exit(0);
}

// ---------------------------------------------------------------------------
// parsing
// ---------------------------------------------------------------------------

struct Matched {
    id: ArgId,
    values: Vec<String>,
    occurrences: usize,
}

struct Matcher {
    args: Vec<Matched>,
}

impl Matcher {
    fn entry(&mut self, id: ArgId) -> &mut Matched {
        if let Some(i) = self.args.iter().position(|m| m.id == id) {
            &mut self.args[i]
        } else {
            self.args.push(Matched {
                id,
                values: Vec::new(),
                occurrences: 0,
            });
            self.args.last_mut().unwrap()
        }
    }
    fn used(&self) -> Vec<ArgId> {
        self.args.iter().map(|m| m.id).collect()
    }
}

pub fn parse() -> Cli {
    let argv: Vec<String> = std::env::args_os()
        .skip(1)
        .map(|a| a.to_string_lossy().into_owned())
        .collect();
    let mut matcher = Matcher { args: Vec::new() };
    let mut pending: Option<ArgId> = None;
    let mut trailing_values = false;

    let mut i = 0;
    while i < argv.len() {
        let arg = &argv[i];
        i += 1;

        if trailing_values {
            // only positionals are accepted here and there are none
            err_unknown_argument(arg, None, &[]);
        }

        if arg == "--" {
            trailing_values = true;
            continue;
        }

        if let Some(rest) = arg.strip_prefix("--") {
            // long argument (a new argument even when a value is pending)
            let (name, value) = match rest.find('=') {
                Some(p) => (&rest[..p], Some(&rest[p..])),
                None => (rest, None),
            };
            match name {
                "help" => {
                    if let Some(v) = value {
                        err_too_many_values(v, "--help");
                    }
                    print_help();
                }
                "version" => {
                    if let Some(v) = value {
                        err_too_many_values(v, "--version");
                    }
                    print_version();
                }
                _ => {}
            }
            match ArgId::from_long(name) {
                Some(id) => {
                    pending = None;
                    let m = matcher.entry(id);
                    m.occurrences += 1;
                    match value {
                        Some(v) => m.values.push(v[1..].to_string()),
                        None => pending = Some(id),
                    }
                }
                None => {
                    let dym = did_you_mean(name, LONG_FLAGS.iter().copied());
                    let mut used = matcher.used();
                    if let Some(s) = dym {
                        if let Some(id) = ArgId::from_long(s) {
                            if !used.contains(&id) {
                                used.push(id);
                            }
                        }
                    }
                    err_unknown_argument(&format!("--{}", name), dym, &used);
                }
            }
            continue;
        }

        if arg.starts_with('-') && arg.len() > 1 {
            // short argument cluster (a new argument even when a value is pending)
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut k = 0;
            while k < chars.len() {
                let c = chars[k];
                k += 1;
                match c {
                    'h' => print_help(),
                    'V' => print_version(),
                    _ => {}
                }
                match ArgId::from_short(c) {
                    Some(id) => {
                        pending = None;
                        let m = matcher.entry(id);
                        m.occurrences += 1;
                        let rest: String = chars[k..].iter().collect();
                        if rest.is_empty() {
                            pending = Some(id);
                        } else {
                            let v = rest.strip_prefix('=').unwrap_or(&rest).to_string();
                            m.values.push(v);
                        }
                        k = chars.len();
                    }
                    None => {
                        err_unknown_argument(&format!("-{}", c), None, &[]);
                    }
                }
            }
            continue;
        }

        // a plain value
        match pending.take() {
            Some(id) => {
                matcher.entry(id).values.push(arg.clone());
            }
            None => err_unknown_argument(arg, None, &[]),
        }
    }

    // validation
    if let Some(id) = pending {
        let m = matcher.entry(id);
        if m.values.is_empty() {
            err_empty_value(id);
        }
    }
    let used = matcher.used();
    let mut cli = Cli {
        number_of_words: 15,
        number_of_sentences: None,
        number_of_secs: None,
        prompt: None,
        supported_language: Language::English,
    };
    for m in &matcher.args {
        if m.values.is_empty() {
            err_empty_value(m.id);
        }
        for v in &m.values {
            match m.id {
                ArgId::SupportedLanguage => {
                    if Language::parse(v).is_none() {
                        err_invalid_possible_value(m.id, v, &used);
                    }
                }
                ArgId::Prompt => {}
                _ => {
                    if let Err(e) = v.parse::<usize>() {
                        err_invalid_value(m.id, v, &int_error_message(v, &e));
                    }
                }
            }
        }
        if m.occurrences > 1 {
            err_multiple(m.id);
        }
    }
    for m in &matcher.args {
        let v = &m.values[0];
        match m.id {
            ArgId::FullSentences => cli.number_of_sentences = v.parse().ok(),
            ArgId::SupportedLanguage => cli.supported_language = Language::parse(v).unwrap(),
            ArgId::Prompt => cli.prompt = Some(v.clone()),
            ArgId::NumberOfSecs => cli.number_of_secs = v.parse().ok(),
            ArgId::NumberOfWords => cli.number_of_words = v.parse().unwrap(),
        }
    }
    cli
}

fn int_error_message(v: &str, e: &std::num::ParseIntError) -> String {
    use std::num::IntErrorKind::*;
    let _ = v;
