cd /workspace && cat > src/cli.rs <<'EOF'
//! Command line parsing, reproducing the behaviour and messages of the original clap based
//! interface.

use std::io::{IsTerminal, Write};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Language {
    English,
    English1k,
    English10k,
}

impl Language {
    fn parse(s: &str) -> Option<Language> {
        match s {
            "english" => Some(Language::English),
            "english1k" => Some(Language::English1k),
            "english10k" => Some(Language::English10k),
            _ => None,
        }
    }
}

const LANGUAGES: [&str; 3] = ["english", "english1k", "english10k"];

#[derive(Debug, Clone)]
pub struct Cli {
    pub number_of_words: usize,
    pub number_of_sentences: Option<usize>,
    pub number_of_secs: Option<usize>,
    pub prompt: Option<String>,
    pub supported_language: Language,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ArgId {
    FullSentences,
    SupportedLanguage,
    Prompt,
    NumberOfSecs,
    NumberOfWords,
}

impl ArgId {
    fn long(self) -> &'static str {
        match self {
            ArgId::FullSentences => "full-sentences",
            ArgId::SupportedLanguage => "supported-language",
            ArgId::Prompt => "prompt",
            ArgId::NumberOfSecs => "number-of-secs",
            ArgId::NumberOfWords => "number-of-words",
        }
    }
    fn short(self) -> char {
        match self {
            ArgId::FullSentences => 'f',
            ArgId::SupportedLanguage => 'l',
            ArgId::Prompt => 'p',
            ArgId::NumberOfSecs => 's',
            ArgId::NumberOfWords => 'w',
        }
    }
    fn value_name(self) -> &'static str {
        match self {
            ArgId::FullSentences => "NUMBER_OF_SENTENCES",
            ArgId::SupportedLanguage => "SUPPORTED_LANGUAGE",
            ArgId::Prompt => "PROMPT",
            ArgId::NumberOfSecs => "NUMBER_OF_SECS",
            ArgId::NumberOfWords => "NUMBER_OF_WORDS",
        }
    }
    /// `--long <VALUE_NAME>`
    fn display(self) -> String {
        format!("--{} <{}>", self.long(), self.value_name())
    }
    fn from_long(s: &str) -> Option<ArgId> {
        ALL.iter().copied().find(|a| a.long() == s)
    }
    fn from_short(c: char) -> Option<ArgId> {
        ALL.iter().copied().find(|a| a.short() == c)
    }
}

/// Declaration order (also the order used for "did you mean" tie breaking).
const ALL: [ArgId; 5] = [
    ArgId::FullSentences,
    ArgId::SupportedLanguage,
    ArgId::Prompt,
    ArgId::NumberOfWords,
    ArgId::NumberOfSecs,
];

const LONG_FLAGS: [&str; 7] = [
    "full-sentences",
    "supported-language",
    "prompt",
    "number-of-words",
    "number-of-secs",
    "help",
    "version",
];

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PStyle {
    Default,
    Error,
    Warning,
    Good,
}

type Piece = (PStyle, String);

fn piece(style: PStyle, s: &str) -> Piece {
    (style, s.to_string())
}

fn render_pieces(pieces: &[Piece], color: bool) -> Vec<u8> {
    let mut out = Vec::new();
    for (style, text) in pieces {
        if color {
            out.extend_from_slice(b"\x1b[0m");
            match style {
                PStyle::Default => {}
                PStyle::Error => out.extend_from_slice(b"\x1b[1m\x1b[31m"),
                PStyle::Warning => out.extend_from_slice(b"\x1b[33m"),
                PStyle::Good => out.extend_from_slice(b"\x1b[32m"),
            }
            out.extend_from_slice(text.as_bytes());
            out.extend_from_slice(b"\x1b[0m");
        } else {
            out.extend_from_slice(text.as_bytes());
        }
    }
    out
}

fn env_allows_color() -> bool {
    match std::env::var_os("TERM") {
        None => return false,
        Some(k) => {
            if k == "dumb" {
                return false;
            }
        }
    }
    std::env::var_os("NO_COLOR").is_none()
}

fn emit(pieces: &[Piece], stderr: bool) {
    let is_tty = if stderr {
        std::io::stderr().is_terminal()
    } else {
        std::io::stdout().is_terminal()
    };
    let color = is_tty && env_allows_color();
    let bytes = render_pieces(pieces, color);
    if stderr {
        let mut e = std::io::stderr().lock();
        let _ = e.write_all(&bytes);
        let _ = e.flush();
    } else {
        let mut o = std::io::stdout().lock();
        let _ = o.write_all(&bytes);
        let _ = o.flush();
    }
}

fn bin_name() -> String {
    std::env::args_os()
        .next()
        .and_then(|a| {
            std::path::Path::new(&a)
                .file_name()
                .map(|f| f.to_string_lossy().into_owned())
        })
        .unwrap_or_else(|| "thokr".to_string())
}

fn usage_line(used: &[ArgId]) -> String {
    if used.is_empty() {
        format!("{} [OPTIONS]", bin_name())
    } else {
        let mut s = bin_name();
        for a in used {
            s.push(' ');
            s.push_str(&a.display());
        }
        s
    }
}

fn error_head() -> Vec<Piece> {
    vec![piece(PStyle::Error, "error:"), piece(PStyle::Default, " ")]
}

fn error_tail(pieces: &mut Vec<Piece>) {
    pieces.push(piece(PStyle::Default, "\n\nFor more information try "));
    pieces.push(piece(PStyle::Good, "--help"));
    pieces.push(piece(PStyle::Default, "\n"));
}

fn usage_block(pieces: &mut Vec<Piece>, used: &[ArgId]) {
    pieces.push(piece(PStyle::Default, "\n\n"));
    pieces.push(piece(
        PStyle::Default,
        &format!("USAGE:\n    {}", usage_line(used)),
    ));
}

fn possible_values_block(pieces: &mut Vec<Piece>) {
    pieces.push(piece(PStyle::Default, "\n\t[possible values: "));
    for (i, v) in LANGUAGES.iter().enumerate() {
        if i > 0 {
            pieces.push(piece(PStyle::Default, ", "));
        }
        pieces.push(piece(PStyle::Good, v));
    }
    pieces.push(piece(PStyle::Default, "]"));
}

fn fail(pieces: Vec<Piece>) -> ! {
    emit(&pieces, true);
    std::process::exit(2);
}

fn err_unknown_argument(arg: &str, did_you_mean: Option<&str>, used: &[ArgId]) -> ! {
    let mut p = error_head();
    p.push(piece(PStyle::Default, "Found argument '"));
    p.push(piece(PStyle::Warning, arg));
    p.push(piece(
        PStyle::Default,
        "' which wasn't expected, or isn't valid in this context",
    ));
    if let Some(s) = did_you_mean {
        p.push(piece(PStyle::Default, "\n\n\tDid you mean '"));
        p.push(piece(PStyle::Good, &format!("--{}", s)));
        p.push(piece(PStyle::Default, "'?"));
    }
    if arg.starts_with('-') {
        p.push(piece(
            PStyle::Default,
            &format!(
                "\n\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`",
                arg, arg
            ),
        ));
    }
    usage_block(&mut p, used);
    error_tail(&mut p);
    fail(p)
}

fn err_empty_value(arg: ArgId) -> ! {
    let mut p = error_head();
    p.push(piece(PStyle::Default, "The argument '"));
    p.push(piece(PStyle::Warning, &arg.display()));
    p.push(piece(
        PStyle::Default,
        "' requires a value but none was supplied",
    ));
    if arg == ArgId::SupportedLanguage {
        possible_values_block(&mut p);
    }
    usage_block(&mut p, &[]);
    error_tail(&mut p);
    fail(p)
}

fn err_multiple(arg: ArgId) -> ! {
    let mut p = error_head();
    p.push(piece(PStyle::Default, "The argument '"));
    p.push(piece(PStyle::Warning, &arg.display()));
    p.push(piece(
        PStyle::Default,
        "' was provided more than once, but cannot be used multiple times",
    ));
    usage_block(&mut p, &[]);
    error_tail(&mut p);
    fail(p)
}

fn err_invalid_value(arg: ArgId, val: &str, msg: &str) -> ! {
    let mut p = error_head();
    p.push(piece(PStyle::Default, "Invalid value "));
    p.push(piece(PStyle::Warning, &format!("\"{}\"", val)));
    p.push(piece(PStyle::Default, " for '"));
    p.push(piece(PStyle::Warning, &arg.display()));
    p.push(piece(PStyle::Default, "': "));
    p.push(piece(PStyle::Default, msg));
    error_tail(&mut p);
    fail(p)
}

fn err_invalid_possible_value(arg: ArgId, val: &str, used: &[ArgId]) -> ! {
    let mut p = error_head();
    p.push(piece(PStyle::Default, &format!("\"{}\"", val)));
    p.push(piece(PStyle::Default, " isn't a valid value for '"));
    p.push(piece(PStyle::Warning, &arg.display()));
    p.push(piece(PStyle::Default, "'"));
    possible_values_block(&mut p);
    if let Some(s) = did_you_mean(val, LANGUAGES.iter().copied()) {
        p.push(piece(PStyle::Default, "\n\n\tDid you mean "));
        p.push(piece(PStyle::Good, &format!("\"{}\"", s)));
        p.push(piece(PStyle::Default, "?"));
    }
    usage_block(&mut p, used);
    error_tail(&mut p);
    fail(p)
}

fn err_too_many_values(val: &str, flag: &str) -> ! {
    let mut p = error_head();
    p.push(piece(PStyle::Default, "The value '"));
    p.push(piece(PStyle::Warning, val));
    p.push(piece(PStyle::Default, "' was provided to '"));
    p.push(piece(PStyle::Warning, flag));
    p.push(piece(
        PStyle::Default,
        "' but it wasn't expecting any more values",
    ));
    p.push(piece(PStyle::Default, "\n\n"));
    p.push(piece(PStyle::Default, &usage_line(&[])));
    error_tail(&mut p);
    fail(p)
}

/// Prints the "stdin must be a tty" style error used by the application itself.
pub fn fail_plain(msg: &str) -> ! {
    let mut e = std::io::stderr().lock();
    let _ = write!(
        e,
        "error: {}\n\nUSAGE:\n    thokr [OPTIONS]\n\nFor more information try --help\n",
        msg
    );
    let _ = e.flush();
    std::process::exit(2);
}

// ---------------------------------------------------------------------------
// "did you mean" (Jaro-Winkler, unlimited common prefix, > 0.8)
// ---------------------------------------------------------------------------

fn jaro(a: &[char], b: &[char]) -> f64 {
    let a_len = a.len();
    let b_len = b.len();
    if a_len == 0 && b_len == 0 {
        return 1.0;
    } else if a_len == 0 || b_len == 0 {
        return 0.0;
    } else if a_len == 1 && b_len == 1 {
        return if a[0] == b[0] { 1.0 } else { 0.0 };
    }
    let search_range = (std::cmp::max(a_len, b_len) / 2) - 1;
    let mut b_consumed = vec![false; b_len];
    let mut matches = 0.0f64;
    let mut transpositions = 0.0f64;
    let mut b_match_index = 0usize;
    for (i, a_elem) in a.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = std::cmp::min(b_len - 1, i + search_range);
        if min_bound > max_bound {
            continue;
        }
        for (j, b_elem) in b.iter().enumerate() {
            if min_bound <= j && j <= max_bound && a_elem == b_elem && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0)
            * ((matches / a_len as f64)
                + (matches / b_len as f64)
                + ((matches - transpositions) / matches))
    }
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let jd = jaro(&a, &b);
    let prefix = a.iter().zip(b.iter()).take_while(|(x, y)| x == y).count();
    let jw = jd + (0.1 * prefix as f64 * (1.0 - jd));
    if jw <= 1.0 {
        jw
    } else {
        1.0
    }
}

fn did_you_mean<'a, I: IntoIterator<Item = &'a str>>(v: &str, candidates: I) -> Option<&'a str> {
    let mut c: Vec<(f64, &str)> = candidates
        .into_iter()
        .map(|pv| (jaro_winkler(v, pv), pv))
        .filter(|(conf, _)| *conf > 0.8)
        .collect();
    c.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
    c.pop().map(|(_, s)| s)
}

// ---------------------------------------------------------------------------
// help / version
// ---------------------------------------------------------------------------

fn print_version() -> ! {
    emit(&[piece(PStyle::Default, "thokr 0.4.1\n")], false);
    std::process::exit(0);
}

fn print_help() -> ! {
    let d = PStyle::Default;
    let g = PStyle::Good;
    let w = PStyle::Warning;
    let mut p: Vec<Piece> = vec![
        piece(d, ""),
        piece(d, ""),
        piece(g, "thokr"),
        piece(d, " "),
        piece(d, "0.4.1"),
        piece(d, "\n"),
        piece(d, ""),
        piece(d, "sleek typing tui with visualized results and historical logging"),
        piece(d, "\n"),
        piece(d, "\n"),
        piece(w, "USAGE:"),
        piece(d, "\n    "),
        piece(d, &usage_line(&[])),
        piece(d, "\n\n"),
        piece(w, "OPTIONS:\n"),
    ];
    struct Opt {
        short: &'static str,
        long: &'static str,
        value: Option<&'static str>,
        help: &'static [&'static str],
    }
    let opts = [
        Opt {
            short: "-f",
            long: "--full-sentences",
            value: Some("<NUMBER_OF_SENTENCES>"),
            help: &["number of sentences to use in test"],
        },
        Opt {
            short: "-h",
            long: "--help",
            value: None,
            help: &["Print help information"],
        },
        Opt {
            short: "-l",
            long: "--supported-language",
            value: Some("<SUPPORTED_LANGUAGE>"),
            help: &[
                "language to pull words from [default: english] [possible values: english, english1k,",
                "english10k]",
            ],
        },
        Opt {
            short: "-p",
            long: "--prompt",
            value: Some("<PROMPT>"),
            help: &["custom prompt to use"],
        },
        Opt {
            short: "-s",
            long: "--number-of-secs",
            value: Some("<NUMBER_OF_SECS>"),
            help: &["number of seconds to run test"],
        },
        Opt {
            short: "-V",
            long: "--version",
            value: None,
            help: &["Print version information"],
        },
        Opt {
            short: "-w",
            long: "--number-of-words",
            value: Some("<NUMBER_OF_WORDS>"),
            help: &["number of words to use in test [default: 15]"],
        },
    ];
    let n = opts.len();
    for (i, o) in opts.iter().enumerate() {
        p.push(piece(d, "    "));
        p.push(piece(g, o.short));
        p.push(piece(d, ", "));
        p.push(piece(g, o.long));
        if let Some(v) = o.value {
            p.push(piece(d, " "));
            p.push(piece(g, v));
        }
        p.push(piece(d, "\n            "));
        for (j, line) in o.help.iter().enumerate() {
            if j > 0 {
                p.push(piece(d, "\n"));
                p.push(piece(d, "            "));
            }
            p.push(piece(d, line));
        }
        if i + 1 < n {
            p.push(piece(d, "\n"));
            p.push(piece(d, "\n"));
        }
    }
    p.push(piece(d, ""));
    p.push(piece(d, ""));
    p.push(piece(d, "\n"));
    emit(&p, false);
    std::process::exit(0);
}

// ---------------------------------------------------------------------------
// parsing
// ---------------------------------------------------------------------------

struct Matched {
    id: ArgId,
    values: Vec<String>,
    occurrences: usize,
}

struct Matcher {
    args: Vec<Matched>,
}

impl Matcher {
    fn entry(&mut self, id: ArgId) -> &mut Matched {
        if let Some(i) = self.args.iter().position(|m| m.id == id) {
            &mut self.args[i]
        } else {
            self.args.push(Matched {
                id,
                values: Vec::new(),
                occurrences: 0,
            });
            self.args.last_mut().unwrap()
        }
    }
    fn used(&self) -> Vec<ArgId> {
        self.args.iter().map(|m| m.id).collect()
    }
}

pub fn parse() -> Cli {
    let argv: Vec<String> = std::env::args_os()
        .skip(1)
        .map(|a| a.to_string_lossy().into_owned())
        .collect();
    let mut matcher = Matcher { args: Vec::new() };
    let mut pending: Option<ArgId> = None;
    let mut trailing_values = false;

    let mut i = 0;
    while i < argv.len() {
        let arg = &argv[i];
        i += 1;

        if trailing_values {
            // only positionals are accepted here and there are none
            err_unknown_argument(arg, None, &[]);
        }

        if arg == "--" {
            trailing_values = true;
            continue;
        }

        if let Some(rest) = arg.strip_prefix("--") {
            // long argument (a new argument even when a value is pending)
            let (name, value) = match rest.find('=') {
                Some(p) => (&rest[..p], Some(&rest[p..])),
                None => (rest, None),
            };
            match name {
                "help" => {
                    if let Some(v) = value {
                        err_too_many_values(v, "--help");
                    }
                    print_help();
                }
                "version" => {
                    if let Some(v) = value {
                        err_too_many_values(v, "--version");
                    }
                    print_version();
                }
                _ => {}
            }
            match ArgId::from_long(name) {
                Some(id) => {
                    pending = None;
                    let m = matcher.entry(id);
                    m.occurrences += 1;
                    match value {
                        Some(v) => m.values.push(v[1..].to_string()),
                        None => pending = Some(id),
                    }
                }
                None => {
                    let dym = did_you_mean(name, LONG_FLAGS.iter().copied());
                    let mut used = matcher.used();
                    if let Some(s) = dym {
                        if let Some(id) = ArgId::from_long(s) {
                            if !used.contains(&id) {
                                used.push(id);
                            }
                        }
                    }
                    err_unknown_argument(&format!("--{}", name), dym, &used);
                }
            }
            continue;
        }

        if arg.starts_with('-') && arg.len() > 1 {
            // short argument cluster (a new argument even when a value is pending)
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut k = 0;
            while k < chars.len() {
                let c = chars[k];
                k += 1;
                match c {
                    'h' => print_help(),
                    'V' => print_version(),
                    _ => {}
                }
                match ArgId::from_short(c) {
                    Some(id) => {
                        pending = None;
                        let m = matcher.entry(id);
                        m.occurrences += 1;
                        let rest: String = chars[k..].iter().collect();
                        if rest.is_empty() {
                            pending = Some(id);
                        } else {
                            let v = rest.strip_prefix('=').unwrap_or(&rest).to_string();
                            m.values.push(v);
                        }
                        k = chars.len();
                    }
                    None => {
                        err_unknown_argument(&format!("-{}", c), None, &[]);
                    }
                }
            }
            continue;
        }

        // a plain value
        match pending.take() {
            Some(id) => {
                matcher.entry(id).values.push(arg.clone());
            }
            None => err_unknown_argument(arg, None, &[]),
        }
    }

    // validation
    if let Some(id) = pending {
        let m = matcher.entry(id);
        if m.values.is_empty() {
            err_empty_value(id);
        }
    }
    let used = matcher.used();
    let mut cli = Cli {
        number_of_words: 15,
        number_of_sentences: None,
        number_of_secs: None,
        prompt: None,
        supported_language: Language::English,
    };
    for m in &matcher.args {
        if m.values.is_empty() {
            err_empty_value(m.id);
        }
        for v in &m.values {
            match m.id {
                ArgId::SupportedLanguage => {
                    if Language::parse(v).is_none() {
                        err_invalid_possible_value(m.id, v, &used);
                    }
                }
                ArgId::Prompt => {}
                _ => {
                    if let Err(e) = v.parse::<usize>() {
                        err_invalid_value(m.id, v, &int_error_message(v, &e));
                    }
                }
            }
        }
        if m.occurrences > 1 {
            err_multiple(m.id);
        }
    }
    for m in &matcher.args {
        let v = &m.values[0];
        match m.id {
            ArgId::FullSentences => cli.number_of_sentences = v.parse().ok(),
            ArgId::SupportedLanguage => cli.supported_language = Language::parse(v).unwrap(),
            ArgId::Prompt => cli.prompt = Some(v.clone()),
            ArgId::NumberOfSecs => cli.number_of_secs = v.parse().ok(),
            ArgId::NumberOfWords => cli.number_of_words = v.parse().unwrap(),
        }
    }
    cli
}

fn int_error_message(v: &str, e: &std::num::ParseIntError) -> String {
    use std::num::IntErrorKind::*;
    let _ = v;
    match e.kind() {
        Empty => "cannot parse integer from empty string".to_string(),
        InvalidDigit => "invalid digit found in string".to_string(),
        PosOverflow => "number too large to fit in target type".to_string(),
        NegOverflow => "number too small to fit in target type".to_string(),
        Zero => "number would be zero for non-zero type".to_string(),
        _ => e.to_string(),
    }
}
EOF
