mod app;
mod buffer;
mod cli;
mod lang;
mod log;
mod rng;
mod sentence;
mod sys;
mod term;
mod thok;
mod unicode;
mod widgets;

use std::io::IsTerminal;
use std::time::Duration;

fn main() {
    let cli = cli::parse();

    if !std::io::stdin().is_terminal() {
        cli::fail_plain("stdin must be a tty");
    }

    let mut app = app::App::new(cli);

    let raw = match term::RawMode::enable() {
        Ok(r) => r,
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    };
    term::enter_alternate_screen();

    let rx = term::spawn_event_thread(Duration::from_millis(100));
    let mut terminal = buffer::Terminal::new();

    terminal.draw(|buf, area| app.render(buf, area));

    loop {
        let ev = match rx.recv() {
            Ok(ev) => ev,
            Err(_) => break,
        };
        match ev {
            term::Event::Key(key) => {
                if let app::Action::Quit = app.on_key(key) {
                    break;
                }
                terminal.draw(|buf, area| app.render(buf, area));
            }
            term::Event::Resize => {
                terminal.draw(|buf, area| app.render(buf, area));
            }
            term::Event::Tick => {
                if app.on_tick() {
                    terminal.draw(|buf, area| app.render(buf, area));
                }
            }
        }
    }

    raw.disable();
    term::leave_alternate_screen_and_show_cursor();
}
