        p.clone()
    } else {
        crate::lang::random_words(cli.supported_language, cli.number_of_words)
    }
}

fn new_thok(cli: &Cli, prompt: String) -> Thok {
    Thok::new(prompt, cli.number_of_words, cli.number_of_secs.map(|s| s as f64))
}

impl App {
    pub fn new(cli: Cli) -> App {
        let prompt = make_prompt(&cli);
        let thok = new_thok(&cli, prompt);
        App { cli, thok }
    }

    pub fn reset(&mut self, new_prompt: bool) {
        let prompt = if new_prompt {
            let cli = &self.cli;
            if let Some(n) = cli.number_of_sentences {
                crate::lang::random_sentences(n)
            } else {
                crate::lang::random_words(cli.supported_language, cli.number_of_words)
            }
        } else {
            self.thok.prompt.clone()
        };
        self.thok = new_thok(&self.cli, prompt);
    }

    fn finish(&mut self) {
        self.thok.calc_results();
        crate::log::save_results(&self.thok);
    }

    pub fn on_key(&mut self, key: KeyEvent) -> Action {
        if key.code == KeyCode::Esc {
            return Action::Quit;
        }
        if key.ctrl {
            if let KeyCode::Char('c') = key.code {
                return Action::Quit;
            }
        }
        match key.code {
            KeyCode::Backspace => {
                if !self.thok.has_finished() {
                    self.thok.backspace();
                }
            }
            KeyCode::Left => self.reset(false),
            KeyCode::Right => self.reset(true),
            KeyCode::Char(c) => {
                if self.thok.has_finished() {
                    match c {
                        'r' => self.reset(false),
                        'n' => self.reset(true),
                        _ => {}
                    }
                } else {
                    self.thok.write(c);
                    if self.thok.has_finished() {
                        self.finish();
                    }
                }
            }
            _ => {}
        }
        Action::Continue
    }

    /// Returns true when the screen needs to be redrawn.
    pub fn on_tick(&mut self) -> bool {
        if self.thok.seconds_remaining.is_some() && self.thok.has_started() && !self.thok.has_finished() {
            self.thok.on_tick();
            if self.thok.has_finished() {
                self.finish();
            }
            true
        } else {
            false
        }
    }

    pub fn render(&self, buf: &mut Buffer, area: Rect) {
        if self.thok.has_finished() {
            self.render_results(buf, area);
        } else {
            self.render_prompt(buf, area);
        }
    }

    fn render_prompt(&self, buf: &mut Buffer, area: Rect) {
        let thok = &self.thok;
        let width = area.width.saturating_sub(10);
        let height = area.height;
        let prompt_len = thok.prompt_chars.len();
        let num_lines: u64 = if width == 0 {
            u64::MAX
        } else {
            ((prompt_len as u64) + width as u64 - 1) / width as u64
        };
        let single_line = num_lines <= 1;
        let top: u16 = if single_line {
            (height.saturating_sub(1)) / 2
        } else {
            let h = height as u64;
            if h > num_lines + 1 {
                ((h - num_lines - 1) / 2) as u16
            } else {
                0
            }
        };
        let x = area.x + 5;
        let mut y = area.y + top;

        if let Some(secs) = thok.seconds_remaining {
            // timer line
            if y < area.bottom() && width > 0 {
                let text = format!("{:.1}", secs);
                let timer_area = Rect {
                    x,
                    y,
                    width,
                    height: 1,
                };
                let style = Style::default().add_modifier(modifier::BOLD | modifier::DIM);
                let graphemes: Vec<StyledGrapheme> = crate::unicode::graphemes(&text)
                    .into_iter()
                    .map(|g| StyledGrapheme { symbol: g, style })
                    .collect();
                render_paragraph(buf, timer_area, &graphemes, Alignment::Center);
            }
            y = y.saturating_add(2);
        }

        if y >= area.bottom() || width == 0 {
            return;
        }
        let text_area = Rect {
            x,
            y,
            width,
            height: area.bottom() - y,
        };

        // build styled graphemes for the prompt
        let base = Style::default().add_modifier(modifier::BOLD);
        let untyped = base.add_modifier(modifier::DIM);
        let cursor = untyped.add_modifier(modifier::UNDERLINED);
        let correct = base.fg(Color::Green);
        let incorrect = base.fg(Color::Red);
        let cursor_idx = thok.input.len();
        let mut buf_chars: Vec<String> = Vec::with_capacity(prompt_len);
        let mut styles: Vec<Style> = Vec::with_capacity(prompt_len);
        for (i, &c) in thok.prompt_chars.iter().enumerate() {
            if i < cursor_idx {
                match thok.input[i].outcome {
                    Outcome::Correct => {
                        buf_chars.push(c.to_string());
                        styles.push(correct);
                    }
                    Outcome::Incorrect => {
                        if c == ' ' {
                            buf_chars.push("·".to_string());
                        } else {
                            buf_chars.push(c.to_string());
                        }
                        styles.push(incorrect);
                    }
                }
            } else if i == cursor_idx {
                buf_chars.push(c.to_string());
                styles.push(cursor);
            } else {
                buf_chars.push(c.to_string());
                styles.push(untyped);
            }
        }
        let joined: String = buf_chars.concat();
        let graphemes_raw = crate::unicode::graphemes(&joined);
        // map graphemes back to styles: graphemes may merge several chars; use the style of the
        // first char of each grapheme
        let mut graphemes = Vec::with_capacity(graphemes_raw.len());
        let mut char_idx = 0usize;
        for g in graphemes_raw {
            let style = styles.get(char_idx).copied().unwrap_or(untyped);
            char_idx += g.chars().count();
            graphemes.push(StyledGrapheme { symbol: g, style });
        }
        let alignment = if single_line { Alignment::Center } else { Alignment::Left };
        render_paragraph(buf, text_area, &graphemes, alignment);
    }

    fn render_results(&self, buf: &mut Buffer, area: Rect) {
        let thok = &self.thok;
        // vertical margin 2, horizontal margin 5
        if area.height <= 4 || area.width <= 10 {
            return;
        }
        let inner = Rect {
            x: area.x + 5,
            y: area.y + 2,
            width: area.width - 10,
            height: area.height - 4,
        };
        let chart_h = std::cmp::max(1, inner.height.saturating_sub(3));
        let chart_area = Rect {
            x: inner.x,
            y: inner.y,
            width: inner.width,
            height: chart_h.min(inner.height),
        };

        let max_x = thok.max_x();
        let max_y = thok.max_y();
        let max_x_label = format!("{:.2}", max_x);
        let max_y_label = format!("{}", max_y);
        let chart = Chart {
            x_labels: vec!["1", &max_x_label],
            y_labels: vec!["0", &max_y_label],
            x_bounds: [1.0, max_x],
            y_bounds: [0.0, max_y],
            x_title: "seconds",
            y_title: "wpm",
            data: &thok.wpm_coords,
        };
        chart.render(buf, chart_area);

        let mut y = chart_area.bottom();
        if y < inner.bottom() {
            let stats = format!(
                "{} wpm   {}% acc   {:.2} sd",
                thok.wpm, thok.accuracy, thok.std_dev
            );
            let style = Style::default().add_modifier(modifier::BOLD);
            let graphemes: Vec<StyledGrapheme> = crate::unicode::graphemes(&stats)
                .into_iter()
                .map(|g| StyledGrapheme { symbol: g, style })
                .collect();
            render_paragraph(
                buf,
                Rect {
                    x: inner.x,
                    y,
                    width: inner.width,
                    height: 1,
                },
                &graphemes,
                Alignment::Center,
            );
        }
        y = y.saturating_add(2);
        if y < inner.bottom() {
            let style = Style::default().add_modifier(modifier::ITALIC);
            render_string(buf, inner.x, y, "(r)etry / (n)ew / (esc)ape", inner.width as usize, style);
        }
    }
}

pub fn language_name(l: Language) -> &'static str {
    match l {
        Language::English => "english",
        Language::English1k => "english1k",
        Language::English10k => "english10k",
    }
}
