//! Random "grammatical" sentence generation used by `--full-sentences`.
//!
//! Sentences have the shape
//! `[The] <modifiers> <noun> <adverbs> <verb> <adverbs> [[the] <modifiers> <noun>].`
//! where modifiers are drawn from ordered categories (opinion, size, age, colour, material).

use crate::rng::Rng;

const OPINION: &str = include_str!("lang/sentence_opinion.txt");
const SIZE: &str = include_str!("lang/sentence_size.txt");
const AGE: &str = include_str!("lang/sentence_age.txt");
const COLOR: &str = include_str!("lang/sentence_color.txt");
const MATERIAL: &str = include_str!("lang/sentence_material.txt");
const ADVERBS: &str = include_str!("lang/sentence_adverbs.txt");
const VERBS: &str = include_str!("lang/sentence_verbs.txt");
const NOUNS: &str = include_str!("lang/sentence_nouns.txt");

struct Lists {
    categories: Vec<Vec<&'static str>>,
    adverbs: Vec<&'static str>,
    verbs: Vec<&'static str>,
    nouns: Vec<&'static str>,
}

fn lines(s: &'static str) -> Vec<&'static str> {
    s.lines().filter(|l| !l.is_empty()).collect()
}

fn lists() -> &'static Lists {
    use std::sync::OnceLock;
    static LISTS: OnceLock<Lists> = OnceLock::new();
    LISTS.get_or_init(|| Lists {
        categories: vec![lines(OPINION), lines(SIZE), lines(AGE), lines(COLOR), lines(MATERIAL)],
        adverbs: lines(ADVERBS),
        verbs: lines(VERBS),
        nouns: lines(NOUNS),
    })
}

fn pluralize_noun(n: &str, rng: &mut Rng) -> String {
    let irregular = match n {
        "man" => Some("men"),
        "woman" => Some("women"),
        "goose" => Some("geese"),
        "ox" => Some("oxen"),
        _ => None,
    };
    if let Some(p) = irregular {
        if rng.chance(0.5) {
            return p.to_string();
        }
    }
    if n.ends_with("ss") {
        return format!("{}es", n);
    }
    let bytes = n.as_bytes();
    if bytes.len() > 1 && n.ends_with('y') && !b"aeiou".contains(&bytes[bytes.len() - 2]) {
        return format!("{}ies", &n[..n.len() - 1]);
    }
    format!("{}s", n)
}

fn third_person(v: &str) -> String {
    if v.ends_with("ss") || v.ends_with("sh") || v.ends_with('x') {
        format!("{}es", v)
    } else {
        format!("{}s", v)
    }
}

/// A noun phrase: optional article, one or two modifiers and a noun. Returns the phrase and
/// whether it is plural.
fn noun_phrase(rng: &mut Rng, l: &Lists) -> (Vec<String>, bool) {
    let plural = rng.chance(0.5);
    let mut words = Vec::new();
    // singular phrases always carry an article, plural ones only half of the time
    if !plural || rng.chance(0.5) {
        words.push("the".to_string());
    }
    let count = if rng.chance(0.5) { 1 } else { 2 };
    let mut picks: Vec<(usize, &str)> = Vec::new();
    for _ in 0..count {
        let cat = rng.below(l.categories.len());
        let word = *rng.pick(&l.categories[cat]);
        picks.push((cat, word));
    }
    picks.sort_by_key(|p| p.0);
    for (_, w) in picks {
        words.push(w.to_string());
    }
    let noun = *rng.pick(&l.nouns);
    if plural {
        words.push(pluralize_noun(noun, rng));
    } else {
        words.push(noun.to_string());
    }
    (words, plural)
}

pub fn generate(rng: &mut Rng) -> String {
    let l = lists();
    let (mut words, plural) = noun_phrase(rng, l);

    let verb = *rng.pick(&l.verbs);
    let verb = if plural { verb.to_string() } else { third_person(verb) };
    let adverb_count = if rng.chance(0.5) { 1 } else { 2 };
    let mut adverbs = Vec::new();
    for _ in 0..adverb_count {
        adverbs.push((*rng.pick(&l.adverbs)).to_string());
    }
    if rng.chance(0.5) {
        words.extend(adverbs);
        words.push(verb);
    } else {
        words.push(verb);
        words.extend(adverbs);
    }

    if rng.chance(0.5) {
        let (obj, _) = noun_phrase(rng, l);
        words.extend(obj);
    }

    let mut sentence = words.join(" ");
    let mut chars = sentence.chars();
    if let Some(first) = chars.next() {
        sentence = first.to_uppercase().collect::<String>() + chars.as_str();
    }
    sentence.push('.');
    sentence
}
