//! Prompt screen rendering.
//!
//! Layout rules (derived from observing the original program):
//!
//! * The text area has a horizontal margin of 5 cells on both sides.
//! * The number of lines the prompt will take is *estimated* as
//!   `ceil(display_width(prompt) / area_width)`; the paragraph itself is word wrapped and may
//!   end up using a different number of lines.
//! * A prompt estimated to fit on a single line is centred horizontally and placed on row
//!   `(height - 1) / 2`.
//! * Longer prompts are left aligned and start on row `(height - lines - 1) / 2`.
//! * With a time limit the remaining seconds are drawn (bold + dim, centred) on the row where
//!   the prompt would otherwise start, followed by an empty row, followed by the prompt.
//!
//! Character styles:
//!
//! * untyped characters: bold + dim
//! * the character under the cursor: bold + dim + underlined
//! * correctly typed characters: bold + green
//! * incorrectly typed characters: bold + red; an expected space is shown as `·`
//!
//! Newlines inside the prompt are not rendered (they are dropped by the text layout), but they
//! still count towards the prompt length used for the test.

use crate::buffer::{modifier, Buffer, Color, Rect, Style};
use crate::thok::{Outcome, Thok};
use crate::widgets::{render_paragraph, Alignment, StyledGrapheme};

/// Computes the text area for the prompt and draws the timer line (if any).
///
/// Returns the area the prompt paragraph should be rendered into and whether the prompt is
/// estimated to fit on a single line (which selects centred alignment).
fn prompt_area(thok: &Thok, buf: &mut Buffer, area: Rect) -> Option<(Rect, bool)> {
    let width = area.width.saturating_sub(10);
    let height = area.height;
    // the layout estimates the number of lines from the display width of the whole prompt
    let prompt_width = crate::unicode::str_width(&thok.prompt);
    let num_lines: u64 = if width == 0 {
        u64::MAX
    } else {
        ((prompt_width as u64) + width as u64 - 1) / width as u64
    };
    let single_line = num_lines <= 1;
    let top: u16 = if single_line {
        (height.saturating_sub(1)) / 2
    } else {
        let h = height as u64;
        if h > num_lines + 1 {
            ((h - num_lines - 1) / 2) as u16
        } else {
            0
        }
    };
    let x = area.x + 5;
    let mut y = area.y + top;

    if let Some(secs) = thok.seconds_remaining {
        // timer line, two rows above the prompt
        if y < area.bottom() && width > 0 {
            let text = format!("{:.1}", secs);
            let timer_area = Rect {
                x,
                y,
                width,
                height: 1,
            };
            let style = Style::default().add_modifier(modifier::BOLD | modifier::DIM);
            let graphemes: Vec<StyledGrapheme> = crate::unicode::graphemes(&text)
                .into_iter()
                .map(|g| StyledGrapheme { symbol: g, style })
                .collect();
            render_paragraph(buf, timer_area, &graphemes, Alignment::Center);
        }
        y = y.saturating_add(2);
    }

    if y >= area.bottom() || width == 0 {
        return None;
    }
    let text_area = Rect {
        x,
        y,
        width,
        height: area.bottom() - y,
    };
    Some((text_area, single_line))
}

/// Returns the (single byte) character under the cursor.
///
/// The original implementation slices the prompt string by *byte* offsets around the cursor
/// position, which is a *character* count. For prompts containing multi-byte characters the
/// offset is not a char boundary and the program panics; we reproduce that behaviour
/// (including the panic location) by performing the very same slice here on every render.
fn current_char(pr: &str, cursor: usize) -> &str {
    let current_chr: &str = &pr[cursor..cursor + 1];
    current_chr
}

pub fn render_prompt(thok: &Thok, buf: &mut Buffer, area: Rect) {
    let (text_area, single_line) = match prompt_area(thok, buf, area) {
        Some(v) => v,
        None => return,
    };

    // build styled graphemes for the prompt
    let base = Style::default().add_modifier(modifier::BOLD);
    let untyped = base.add_modifier(modifier::DIM);
    let cursor = untyped.add_modifier(modifier::UNDERLINED);
    let correct = base.fg(Color::Green);
    let incorrect = base.fg(Color::Red);
    let cursor_idx = thok.input.len();
    let _ = current_char(&thok.prompt, cursor_idx);
    let prompt_len = thok.prompt_chars.len();
    let mut buf_chars: Vec<String> = Vec::with_capacity(prompt_len);
    let mut styles: Vec<Style> = Vec::with_capacity(prompt_len);
    for (i, &c) in thok.prompt_chars.iter().enumerate() {
        if i < cursor_idx {
            match thok.input[i].outcome {
                Outcome::Correct => {
                    buf_chars.push(c.to_string());
                    styles.push(correct);
                }
                Outcome::Incorrect => {
                    if c == ' ' {
                        buf_chars.push("·".to_string());
                    } else {
                        buf_chars.push(c.to_string());
                    }
                    styles.push(incorrect);
                }
            }
        } else if i == cursor_idx {
            buf_chars.push(c.to_string());
            styles.push(cursor);
        } else {
            buf_chars.push(c.to_string());
            styles.push(untyped);
        }
    }
    let joined: String = buf_chars.concat();
    let graphemes_raw = crate::unicode::graphemes(&joined);
    // map graphemes back to styles: graphemes may merge several chars; use the style of the
    // first char of each grapheme
    let mut graphemes = Vec::with_capacity(graphemes_raw.len());
    let mut char_idx = 0usize;
    for g in graphemes_raw {
        let style = styles.get(char_idx).copied().unwrap_or(untyped);
        char_idx += g.chars().count();
        // newlines inside a span are dropped by the text layout
        if g == "\n" {
            continue;
        }
        graphemes.push(StyledGrapheme { symbol: g, style });
    }
    let alignment = if single_line { Alignment::Center } else { Alignment::Left };
    render_paragraph(buf, text_area, &graphemes, alignment);
}
EOF
